TYPE FB_State :
(
    IDLE,
    OPENING,
    CLOSING,
    FAULT
);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state : FB_State := FB_State#IDLE;
    openBtnPrev : BOOL := FALSE;
    closeBtnPrev : BOOL := FALSE;
    openRising : BOOL;
    closeRising : BOOL;
END_VAR

openRising := openBtn AND NOT openBtnPrev;
closeRising := closeBtn AND NOT closeBtnPrev;

CASE state OF
    FB_State#IDLE:
        motorUp := FALSE;
        motorDown := FALSE;
        errorFlag := FALSE;
        IF openRising AND NOT openLimit THEN
            state := FB_State#OPENING;
        ELSIF closeRising AND NOT closeLimit THEN
            state := FB_State#CLOSING;
        END_IF;

    FB_State#OPENING:
        IF obstacle THEN
            motorUp := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;
            state := FB_State#FAULT;
        ELSE
            motorUp := TRUE;
            motorDown := FALSE;
            errorFlag := FALSE;
            IF openLimit THEN
                motorUp := FALSE;
                state := FB_State#IDLE;
            END_IF;
        END_IF;

    FB_State#CLOSING:
        IF obstacle THEN
            IF openLimit THEN
                motorUp := FALSE;
                motorDown := FALSE;
                errorFlag := TRUE;
                state := FB_State#FAULT;
            ELSE
                motorDown := FALSE;
                motorUp := TRUE;
                errorFlag := FALSE;
                state := FB_State#OPENING;
            END_IF;
        ELSE
            motorUp := FALSE;
            motorDown := TRUE;
            errorFlag := FALSE;
            IF closeLimit THEN
                motorDown := FALSE;
                state := FB_State#IDLE;
            END_IF;
        END_IF;

    FB_State#FAULT:
        motorUp := FALSE;
        motorDown := FALSE;
        errorFlag := TRUE;
        IF openBtn AND closeBtn THEN
            state := FB_State#IDLE;
            errorFlag := FALSE;
        END_IF;
END_CASE;

openBtnPrev := openBtn;
closeBtnPrev := closeBtn;

END_FUNCTION_BLOCK

